  1	import type { Order, LineItem, Money } from './types';
  2	import { roundHalfEven } from '../money/round';
  3	import { taxRateFor } from '../tax/rates';
  4	
  5	/** Sum of line item amounts in minor units, per currency. */
  6	export interface Totals {
  7	  subtotal: Money;
  8	  tax: Money;
  9	  shipping: Money;
 10	  total: Money;
 11	}
 12	
 13	const ZERO_DECIMAL = new Set(['JPY', 'KRW']);
 14	
 15	export function minorUnits(currency: string): number {
 16	  return ZERO_DECIMAL.has(currency) ? 0 : 2;
 17	}
 18	
 19	export function toMinor(amount: number, currency: string): number {
 20	  const digits = minorUnits(currency);
 21	  return roundHalfEven(amount * 10 ** digits);
 22	}
 23	
 24	export function money(amountMinor: number, currency: string): Money {
 25	  return { amountMinor, currency };
 26	}
 27	
 28	function shippingFor(order: Order): Money {
 29	  if (order.shipping?.method === 'pickup') return money(0, order.currency);
 30	  const base = order.shipping?.method === 'express' ? 1500 : 500;
 31	  return money(order.currency === 'JPY' ? base * 1 : base, order.currency);
 32	}
 33	
 34	function assertSameCurrency(a: Money, b: Money): void {
 35	  if (a.currency !== b.currency) {
 36	    throw new Error(`currency mismatch: ${a.currency} vs ${b.currency}`);
 37	  }
 38	}
 39	
 40	export function add(a: Money, b: Money): Money {
 41	  assertSameCurrency(a, b);
 42	  return money(a.amountMinor + b.amountMinor, a.currency);
 43	}
 44	
 45	export function multiply(m: Money, factor: number): Money {
 46	  return money(roundHalfEven(m.amountMinor * factor), m.currency);
 47	}
 48	
 49	function discountFor(order: Order, subtotal: Money): Money {
 50	  const code = order.discount?.code;
 51	  if (!code) return money(0, subtotal.currency);
 52	  if (order.discount?.percent) {
 53	    return multiply(subtotal, order.discount.percent / 100);
 54	  }
 55	  return money(order.discount?.amountMinor ?? 0, subtotal.currency);
 56	}
 57	
 58	function taxFor(order: Order, taxable: Money): Money {
 59	  const rate = taxRateFor(order.shippingAddress?.country ?? 'US', order.shippingAddress?.region);
 60	  return multiply(taxable, rate);
 61	}
