 85	export function computeTotals(order: Order, rates: Record<string, number>): Totals {
 86	  let subtotal = money(0, order.currency);
 87	  for (const item of order.items) {
 88	    const cur = item.price.currency;
 89	    const rate = cur === order.currency ? 1 : rates[`${cur}:${order.currency}`];
 90	    if (rate === undefined) throw new Error(`no rate for ${cur} -> ${order.currency}`);
 91	    const line = multiply(money(item.price.amountMinor, order.currency), rate * item.quantity);
 92	    subtotal = add(subtotal, line);
 93	  }
 94	  const discount = discountFor(order, subtotal);
 95	  const taxable = money(Math.max(0, subtotal.amountMinor - discount.amountMinor), order.currency);
 96	  const tax = taxFor(order, taxable);
 97	  const shipping = shippingFor(order);
 98	  const total = add(add(taxable, tax), shipping);
 99	  return { subtotal, tax, shipping, total };
