19	export async function buildOrder(input: OrderInput, ctx: BuildContext): Promise<Order> {
20	  const valid = validateOrderInput(input);
21	  const order: Order = {
22	    id: `ord_${ctx.requestId.slice(0, 4)}`,
23	    currency: valid.currency,
24	    items: valid.items.map(toLineItem),
25	    shipping: valid.shipping,
26	    shippingAddress: valid.shippingAddress,
27	    discount: valid.discount,
28	    createdAt: ctx.now.toISOString(),
29	  };
30	  const rates = await loadRates(order.currency);
